				com_shketlabs_games_streetscafe_Debug.out("tickOfflineTimeForUser: Employee index=" + i + ", Job=" + employee.job + ", TimeElapsedMs=" + timeElapsedMs + ", OldHappiness=" + oldHappiness + ", NewHappiness=" + employee.happiness);
