		,tick: function(param1) {
			if(this.isClosing) {
				var chooserPosY = Constants.GameHeight + 88;
				if(this.itemChooser.get_y() < chooserPosY) {
					this.itemChooser.set_y(this.itemChooser.get_y() + 7);
					if(this.itemChooser.get_y() >= 420) {
						this.sceneLayer.set_y(this.sceneLayer.get_y() + 7);
					}
				} else {
					this.removeObject(this.itemChooser);
					var _blockIdx = 2;
					var _users = com_shketlabs_games_streetscafe_GameWorld.cachedGameUsers[_blockIdx];
					com_shketlabs_games_streetscafe_WorldStreet.streetUsers = _users;
					com_shketlabs_games_streetscafe_WorldStreet.streetUserList = new com_shketlabs_games_streetscafe_WorldFriendsList(com_shketlabs_games_streetscafe_GameWorld.allUserFriends,false,false);
					com_shketlabs_games_streetscafe_WorldStreet.streetUserList.set_drawPriority(10000);
					this.destroy();
					com_shketlabs_games_streetscafe_Engine.setActiveWorld(new com_shketlabs_games_streetscafe_WorldStreet(com_shketlabs_games_streetscafe_GameWorld.gameUser,false,null,true));
				}
			} else if(this.itemChooser.get_y() > this.chooserTargetY) {
				this.itemChooser.set_y(this.itemChooser.get_y() - 7);
				if(this.itemChooser.get_y() <= 420) {
					this.sceneLayer.set_y(this.sceneLayer.get_y() - 7);
				}
			}
		}
