		,isGardenValid: function(posX,posY) {
			var isAcceptSeed = false;
			if(posX >= 2 && posY <= -6 && posX <= 6 && posY >= -10) {
				var areaNumber = this.getGardenAreaNumber(posX,posY);
				var gardenArea = this.getGardenTileByNumber(areaNumber);
				var locked = gardenArea.additionalData.locked;
				isAcceptSeed = !locked;
			}
			return isAcceptSeed;
		}
		,getGardenAreaNumber: function(posX,posY) {
			var areaNumber = 0;
			switch(posX) {
			case 2:
				if(posY == -10) {
					areaNumber = 2;
				}
				if(posY == -8) {
					areaNumber = 1;
				}
				if(posY == -6) {
					areaNumber = 0;
				}
				break;
			case 4:
				if(posY == -10) {
					areaNumber = 5;
				}
				if(posY == -8) {
					areaNumber = 4;
				}
				if(posY == -6) {
					areaNumber = 3;
				}
				break;
			case 6:
				if(posY == -10) {
					areaNumber = 8;
				}
				if(posY == -8) {
					areaNumber = 7;
				}
				if(posY == -6) {
					areaNumber = 6;
				}
				break;
			}
			return areaNumber;
		}
